import{_ as o,a0 as p,w as l,s as d,ao as r,I as t,x as s,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"我正在運行的 Linux 是什麼版本？ | LCTT x X-CMD","titleTemplate":false,"description":"我正在運行的 Linux 是什麼版本？ | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我正在運行的 Linux 是什麼版本？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我正在運行的 Linux 是什麼版本？ | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180612 What version of Linux am I running","title":"我正在運行的 Linux 是什麼版本？","tag":"201806","desc":""},"relativePath":"201806/20180612 What version of Linux am I running.md","filePath":"[post].md"}'),u={name:"201806/20180612 What version of Linux am I running.md"};function c(h,e,g,k,f,x){const a=p("Link");return l(),d("div",null,[e[15]||(e[15]=r(`<h1 id="我正在運行的-linux-是什麼版本" tabindex="-1">我正在運行的 Linux 是什麼版本？ <a class="header-anchor" href="#我正在運行的-linux-是什麼版本" aria-label="Permalink to “我正在運行的 Linux 是什麼版本？”">​</a></h1><blockquote><p>掌握這些快捷命令以找出你正在運行的 Linux 系統的內核版本和發行版。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/yearbook-haff-rx-linux-file-lead_0.png?itok=-i0NNfDC" alt=""></p><p>“什麼版本的 Linux ？”這個問題可能意味着兩個不同的東西。嚴格地説，Linux 是內核，所以問題可以特指內核的版本號，或者 “Linux” 可以更通俗地用來指整個發行版，就像在 Fedora Linux 或 Ubuntu Linux 中一樣。</p><p>兩者都很重要，你可能需要知道其中一個或全部答案來修復系統中的問題。例如，瞭解已安裝的內核版本可能有助於診斷帶有專有驅動程序的問題，並且確定正在運行的發行版將幫助你快速確定是否應該使用 <code>apt</code>、 <code>dnf</code>、 <code>yum</code> 或其他命令來安裝軟件包。</p><p>以下內容將幫助你瞭解 Linux 內核的版本和/或系統上正在運行的 Linux 發行版是什麼。</p><h3 id="如何找到-linux-內核版本" tabindex="-1">如何找到 Linux 內核版本 <a class="header-anchor" href="#如何找到-linux-內核版本" aria-label="Permalink to “如何找到 Linux 內核版本”">​</a></h3><p>要找出哪個 Linux 內核版本正在運行，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname -srm</span></span></code></pre></div><p>或者，可以使用更長，更具描述性的各種標誌的版本來運行該命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname --kernel-name --kernel-release --machine</span></span></code></pre></div><p>無論哪種方式，輸出都應該類似於以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux 4.16.10-300.fc28.x86_64 x86_64</span></span></code></pre></div><p>這為你提供了（按順序）：內核名稱、內核版本以及運行內核的硬件類型。在上面的情況下，內核是 Linux ，版本 4.16.10-300.fc28.x86_64 ，運行於 x86_64 系統。</p><p>有關 <code>uname</code> 命令的更多信息可以通過運行 <code>man uname</code> 找到。</p><h3 id="如何找出-linux-發行版" tabindex="-1">如何找出 Linux 發行版 <a class="header-anchor" href="#如何找出-linux-發行版" aria-label="Permalink to “如何找出 Linux 發行版”">​</a></h3><p>有幾種方法可以確定系統上運行的是哪個發行版，但最快的方法是檢查 <code>/etc/os-release</code> 文件的內容。此文件提供有關發行版的信息，包括但不限於發行版名稱及其版本號。某些發行版的 <code>os-release</code> 文件包含比其他發行版更多的細節，但任何包含 <code>os-release</code> 文件的發行版都應該提供發行版的名稱和版本。</p><p>要查看 <code>os-release</code> 文件的內容，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/os-release</span></span></code></pre></div><p>在 Fedora 28 中，輸出如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME=Fedora</span></span>
<span class="line"><span>VERSION=&quot;28 (Workstation Edition)&quot;</span></span>
<span class="line"><span>ID=fedora</span></span>
<span class="line"><span>VERSION_ID=28</span></span>
<span class="line"><span>PLATFORM_ID=&quot;platform:f28&quot;</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Fedora 28 (Workstation Edition)&quot;</span></span>
<span class="line"><span>ANSI_COLOR=&quot;0;34&quot;</span></span>
<span class="line"><span>CPE_NAME=&quot;cpe:/o:fedoraproject:fedora:28&quot;</span></span>
<span class="line"><span>HOME_URL=&quot;https://fedoraproject.org/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://fedoraproject.org/wiki/Communicating_and_getting_help&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugzilla.redhat.com/&quot;</span></span>
<span class="line"><span>REDHAT_BUGZILLA_PRODUCT=&quot;Fedora&quot;</span></span>
<span class="line"><span>REDHAT_BUGZILLA_PRODUCT_VERSION=28</span></span>
<span class="line"><span>REDHAT_SUPPORT_PRODUCT=&quot;Fedora&quot;</span></span>
<span class="line"><span>REDHAT_SUPPORT_PRODUCT_VERSION=28</span></span>
<span class="line"><span>PRIVACY_POLICY_URL=&quot;https://fedoraproject.org/wiki/Legal:PrivacyPolicy&quot;</span></span>
<span class="line"><span>VARIANT=&quot;Workstation Edition&quot;</span></span>
<span class="line"><span>VARIANT_ID=workstation</span></span></code></pre></div><p>如上面那個例子展示的那樣，Fedora 的 <code>os-release</code> 文件提供了發行版的名稱和版本，但它也標識這個安裝的變體（“Workstation Edition”）。如果我們在 Fedora 28 服務器版本上運行相同的命令，<code>os-release</code> 文件的內容會反映在 <code>VARIANT</code> 和 <code>VARIANT_ID</code> 行中。</p><p>有時候知道一個發行版是否與另一個發行版相似非常有用，因此 <code>os-release</code> 文件可以包含一個 <code>ID_LIKE</code> 行，用於標識正在運行的是基於什麼的發行版或類似的發行版。例如，Red Hat Linux 企業版的 <code>os-release</code> 文件包含 <code>ID_LIKE</code> 行，聲明 RHEL 與 Fedora 類似；CentOS 的 <code>os-release</code> 文件聲明 CentOS 與 RHEL 和 Fedora 類似。如果你正在使用基於另一個發行版的發行版並需要查找解決問題的説明，那麼 <code>ID_LIKE</code> 行非常有用。</p><p>CentOS 的 <code>os-release</code> 文件清楚地表明它就像 RHEL 一樣，所以在各種論壇中關於 RHEL 的文檔，問題和答案應該（大多數情況下）適用於 CentOS。CentOS 被設計成一個 RHEL 近親，因此在某些字段它更兼容其 <code>ID_LIKE</code> 系統的字段。如果你找不到正在運行的發行版的信息，檢查有關 “類似” 發行版的答案總是一個好主意。</p><p>有關 <code>os-release</code> 文件的更多信息可以通過運行 <code>man os-release</code> 命令來查找。</p><hr>`,26)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),n(a,{href:"https://opensource.com/article/18/6/linux-version"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/18/6/linux-version",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),n(a,{href:"https://opensource.com/users/holmja"},{default:i(()=>[...e[2]||(e[2]=[s("Joshua Allen Holm",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),n(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...e[4]||(e[4]=[s("MjSeven",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const _=o(u,[["render",c]]);export{b as __pageData,_ as default};
